create table if not exists public.inventory_tool_loans (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), branch_id uuid not null references public.branches(id), project_id uuid references public.projects(id), stock_id uuid not null references public.inventory_stock(id), code text not null unique, worker_name text not null, expected_return_date date, returned_at timestamptz, status text not null default 'active' check (status in ('active','returned','damaged','cancelled')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists inventory_tool_loans_company_status_idx on public.inventory_tool_loans(company_id,status,created_at desc);
alter table public.inventory_tool_loans enable row level security;
create policy inventory_tool_loans_member_read on public.inventory_tool_loans for select to authenticated using (exists(select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.company_id=inventory_tool_loans.company_id));
create policy inventory_tool_loans_manager_write on public.inventory_tool_loans for all to authenticated using (private.inventory_manager_for(company_id)) with check (private.inventory_manager_for(company_id));
